// Components of the overview and catalog Page layouts. They are generated by
// the layout step (plugins/remark-layouts.mjs) from the page's Markdown and
// its data file, never written by hand: a page chooses its layout in front
// matter (`layout: overview`, `layout: catalog`). Everything is in the
// server-rendered HTML; the catalog's search and filter chips only hide items
// in the browser.
import React, { Children, cloneElement, isValidElement, useId, useMemo, useState } from 'react';
import clsx from 'clsx';

// ---- overview -----------------------------------------------------------------

export function OverviewGrid({ children }) {
  return <div className="wso2-overview-grid">{children}</div>;
}

// One card: the section's heading (kept as a heading, so it has its anchor
// and reads in the page outline), its text and its links.
export function OverviewCard({ level, children }) {
  return <section className={clsx('wso2-overview-card', `wso2-overview-card--h${level ?? 2}`)}>{children}</section>;
}

// ---- catalog --------------------------------------------------------------------

const matchesQuery = (props, q) => {
  if (!q) return true;
  const hay = [props.name, props.categoryLabel, ...(props.tags ? String(props.tags).split('|') : [])].join(' ').toLowerCase();
  return q.toLowerCase().split(/\s+/).filter(Boolean).every((w) => hay.includes(w));
};

export function Catalog({ categories, children }) {
  const chips = useMemo(() => {
    try { return categories ? JSON.parse(categories) : []; } catch { return []; }
  }, [categories]);
  const [query, setQuery] = useState('');
  const [active, setActive] = useState([]);
  const id = useId();
  const items = Children.toArray(children).filter(isValidElement);
  const filtering = Boolean(query.trim()) || active.length > 0;
  const shown = items.map((c) => matchesQuery(c.props, query.trim()) && (!active.length || active.includes(c.props.category)));
  const count = shown.filter(Boolean).length;
  const toggle = (chip) => setActive((a) => (a.includes(chip) ? a.filter((x) => x !== chip) : [...a, chip]));
  return (
    <div className="wso2-layout-catalog">
      <div className="wso2-layout-catalog__controls" data-search-exclude="">
        <label className="wso2-layout-catalog__search" htmlFor={`${id}-q`}>
          <span className="wso2-sr-only">Search by name</span>
          <input id={`${id}-q`} type="search" placeholder="Search by name" value={query} onChange={(e) => setQuery(e.target.value)} autoComplete="off" />
        </label>
        {chips.length > 0 && (
          <div className="wso2-layout-catalog__chips" role="group" aria-label="Filter by category">
            {chips.map((c) => (
              <button key={c.id} type="button" className="wso2-layout-catalog__chip" aria-pressed={active.includes(c.id)} onClick={() => toggle(c.id)}>{c.label}</button>
            ))}
          </div>
        )}
      </div>
      <p className="wso2-layout-catalog__status" role="status">{filtering ? (count ? `${count} of ${items.length} shown` : 'Nothing matches. Clear the search or the filters to see everything.') : ''}</p>
      <ul className="wso2-layout-catalog__grid">
        {items.map((c, i) => cloneElement(c, { hidden: !shown[i] }))}
      </ul>
    </div>
  );
}

const STATUS = { beta: 'Beta', deprecated: 'Deprecated' };

// data-category-label and data-tags are read by the item's search record
// (plugins/platform-outputs.mjs), so a search for a category or tag finds it.
export function CatalogItem({ id, category, categoryLabel, tags, status, hidden, children }) {
  return (
    <li className="wso2-layout-catalog__item" id={id ? `catalog-${id}` : undefined} data-category={category}
      data-category-label={categoryLabel || undefined} data-tags={tags ? String(tags).split('|').join(' ') : undefined} hidden={hidden || undefined}>
      {status && <span className={clsx('wso2-layout-catalog__badge', `wso2-layout-catalog__badge--${status}`)}>{STATUS[status] ?? status}</span>}
      {children}
    </li>
  );
}

export function CatalogLogo({ children }) {
  return <div className="wso2-layout-catalog__logo" aria-hidden="true">{children}</div>;
}

export default { OverviewGrid, OverviewCard, Catalog, CatalogItem, CatalogLogo };
